from ver.order import key


def test_prerelease_first():
    assert sorted(["1.0.0", "1.0.0-alpha"], key=key) == ["1.0.0-alpha", "1.0.0"]


def test_numeric():
    assert sorted(["1.10.0", "1.2.0"], key=key) == ["1.2.0", "1.10.0"]


def test_prerelease_is_older():
    # pre-releases sort before their release, even nightly builds
    assert sorted(["1.0.0-alpha", "1.0.0"], key=key) == ["1.0.0-alpha", "1.0.0"]

